    const key=row.sha256+':'+selectionKey(selection);
    if(c.model.descriptions.has(key))return c.model.descriptions.get(key);
    const value=await spatial(c,'describe',{selection},signal);
    c.model.descriptions.set(key,value);
    return value;
  }

